"""Generate the full-rate received-signal mixers and reproducible FIR RTL."""
from pathlib import Path
import json
import shutil
import numpy as np

P = Path(__file__).resolve().parents[1]
template = '''`timescale 1ns / 1ps
// Generated by scripts/design_fullrate_fir.py. 10 MSPS, symmetric Q17 FIR.
// Eight time slots per sample, parallel DSP lanes, fixed 16-clock latency.
module translation_fir_@MODE@ (
    input wire clk,input wire rst_n,input wire input_valid,
    input wire signed [15:0] sample_in,
    output reg output_valid,output reg signed [15:0] sample_out,output reg overrun
);
    localparam integer TAPS=@TAPS@, PRODUCTS=(TAPS+1)/2, LANES=32;
    // Packed delay line has the same registers as an unpacked array but avoids
    // hundreds of separate simulator events on each received sample.
    reg [16*TAPS-1:0] history;
    reg feeding;
    reg [2:0] slot;
    reg pair_valid,product_valid;
    reg [2:0] pair_slot,product_slot;
    reg signed [16:0] pair_value [0:LANES-1];
    reg signed [15:0] pair_coefficient [0:LANES-1];
    (* use_dsp="yes" *) reg signed [32:0] product [0:LANES-1];
    reg signed [39:0] accumulator [0:LANES-1];
    reg [5:0] sum_valid;
    reg signed [40:0] sum1 [0:15];
    reg signed [41:0] sum2 [0:7];
    reg signed [42:0] sum3 [0:3];
    reg signed [43:0] sum4 [0:1];
    reg signed [44:0] sum5;
    wire signed [44:0] rounded=(sum5+45'sd32768)>>>16;
    integer i;
    function signed [15:0] history_sample;
        input integer index;
        begin history_sample=history[16*index+:16];end
    endfunction
    function signed [15:0] coefficient;
        input integer index;
        begin
            case(index)
@COEFFICIENTS@
                default: coefficient=0;
            endcase
        end
    endfunction
    always @(posedge clk or negedge rst_n)begin
        if(!rst_n)begin
            feeding<=0;slot<=0;pair_valid<=0;product_valid<=0;
            pair_slot<=0;product_slot<=0;sum_valid<=0;sum5<=0;
            output_valid<=0;sample_out<=0;overrun<=0;
            history<=0;
            for(i=0;i<LANES;i=i+1)begin
                pair_value[i]<=0;pair_coefficient[i]<=0;product[i]<=0;accumulator[i]<=0;
            end
            for(i=0;i<16;i=i+1)sum1[i]<=0;
            for(i=0;i<8;i=i+1)sum2[i]<=0;
            for(i=0;i<4;i=i+1)sum3[i]<=0;
            for(i=0;i<2;i=i+1)sum4[i]<=0;
        end else begin
            output_valid<=sum_valid[5];
            sum_valid<={sum_valid[4:0],product_valid && product_slot==7};
            pair_valid<=feeding;product_valid<=pair_valid;
            pair_slot<=slot;product_slot<=pair_slot;
            if(input_valid)begin
                if(feeding)overrun<=1;
                history<={history[16*(TAPS-1)-1:0],sample_in};slot<=0;feeding<=1;
            end else if(feeding)begin
                if(slot==7)feeding<=0;else slot<=slot+1'b1;
            end
            if(feeding)for(i=0;i<LANES;i=i+1)begin
                if(8*i+slot<PRODUCTS)begin
                    if(8*i+slot==PRODUCTS-1)
                        pair_value[i]<=history_sample(8*i+slot);
                    else pair_value[i]<=$signed(history_sample(8*i+slot))
                        +$signed(history_sample(TAPS-1-(8*i+slot)));
                    pair_coefficient[i]<=coefficient(8*i+slot);
                end else begin pair_value[i]<=0;pair_coefficient[i]<=0;end
            end
            if(pair_valid)for(i=0;i<LANES;i=i+1)product[i]<=pair_value[i]*pair_coefficient[i];
            if(product_valid)for(i=0;i<LANES;i=i+1)begin
                if(product_slot==0)accumulator[i]<={{7{product[i][32]}},product[i]};
                else accumulator[i]<=accumulator[i]+{{7{product[i][32]}},product[i]};
            end
            if(sum_valid[0])for(i=0;i<16;i=i+1)
                sum1[i]<=$signed(accumulator[2*i])+$signed(accumulator[2*i+1]);
            if(sum_valid[1])for(i=0;i<8;i=i+1)sum2[i]<=$signed(sum1[2*i])+$signed(sum1[2*i+1]);
            if(sum_valid[2])for(i=0;i<4;i=i+1)sum3[i]<=$signed(sum2[2*i])+$signed(sum2[2*i+1]);
            if(sum_valid[3])for(i=0;i<2;i=i+1)sum4[i]<=$signed(sum3[2*i])+$signed(sum3[2*i+1]);
            if(sum_valid[4])sum5<=$signed(sum4[0])+$signed(sum4[1]);
            if(sum_valid[5])begin
                // Q17 coefficients, gain two compensates the real cosine mixer.
                if(rounded>45'sd32767)sample_out<=16'sh7fff;
                else if(rounded< -45'sd32768)sample_out<=16'sh8000;
                else sample_out<=rounded[15:0];
            end
        end
    end
endmodule
'''

def design():
    reports = {}
    for mode, taps, cutoff, passband, stopband in [('5a',81,400000,100000,900000),
                                                ('5b',401,550000,500000,600000)]:
        x=np.arange(taps)-(taps-1)/2
        h=2*cutoff/10000000*np.sinc(2*cutoff/10000000*x)*np.kaiser(taps,6)
        h/=h.sum()
        q=np.rint(h*131072).astype(int)
        q[taps//2]+=131072-int(q.sum())
        assert np.array_equal(q,q[::-1]) and max(abs(q))<32768
        coeff='\n'.join(f"                {i}: coefficient={'-' if c<0 else ''}16'sd{abs(c)};"
                        for i,c in enumerate(q[:taps//2+1]))
        rtl=template.replace('@MODE@',mode).replace('@TAPS@',str(taps)).replace('@COEFFICIENTS@',coeff)
        (P / f'rtl/translation_fir_{mode}.v').write_text(rtl,encoding='utf-8')
        f=np.linspace(0,5000000,20001)
        response=abs(np.exp(-2j*np.pi*f[:,None]/10000000*np.arange(taps))@(q/131072))
        reports[mode.upper()]={'sample_hz':10000000,'taps':taps,'cutoff_hz':cutoff,'kaiser_beta':6,
            'coefficients_q':17,'dc_gain_before_mixer_compensation':float(q.sum()/131072),
            'passband_hz':[0,passband],
            'passband_min_db':float(20*np.log10(response[f<=passband].min())),
            'passband_max_db':float(20*np.log10(response[f<=passband].max())),
            'stopband_hz':[stopband,5000000],
            'stopband_max_db':float(20*np.log10(max(response[f>=stopband].max(),1e-30))),
            'group_delay_us':(taps-1)/2/10,
            'coefficients':q.tolist()}
    (P/'output/fullrate_fir_design.json').write_text(json.dumps(reports,indent=2)+'\n',encoding='utf-8')
    print(json.dumps({k:{p:v for p,v in d.items() if p!='coefficients'} for k,d in reports.items()},indent=2))

if __name__=='__main__':
    design()
